class BitLinear(nn.Module):
    def __init__(self, in_features, out_features):
        super().__init__()
        self.weight = nn.Parameter(torch.randn(out_features, in_features))

    def forward(self, x):
        # Quantize weights to {-1, 0, +1}
        gamma = self.weight.abs().mean()
        w_quant = (self.weight / gamma).round().clamp(-1, 1)
        # Pure integer additions instead of float multiply!
        return F.linear(x, w_quant) * gamma
